// Validate input and build the dead-letter record. Does not store anything itself.
const body = $input.first().json.body;
if (!body || typeof body !== 'object' || body.payload === undefined) {
  return [{ json: { valid: false, error: 'body.payload is required' } }];
}
const rid = (globalThis.crypto && crypto.randomUUID) ? crypto.randomUUID() : String(Date.now()) + '-' + Math.random().toString(16).slice(2);
return [{ json: {
  valid: true,
  dlq_id: rid,
  source: String(body.source || 'unknown'),
  status: 'pending',
  reason: String(body.reason || 'unspecified'),
  attempts: String(body.attempts ?? ''),
  last_status: String(body.last_status ?? ''),
  last_error: String(body.last_error ?? ''),
  payload_json: JSON.stringify(body.payload),
  received_at: new Date().toISOString()
} }];
